import React, {useEffect,useMemo,useState,createContext,useContext} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,LayoutDashboard,Users,GraduationCap,BookOpen,ClipboardCheck,ChartNoAxesCombined,AlertTriangle,ShieldCheck,Settings,LogOut,Database,Link2,BrainCircuit,FileSpreadsheet,Plus,RefreshCw,Search,Download,Bell,CalendarDays,MessageSquare,ClipboardList,Menu,X,ChevronRight,CheckCircle2,Moon,Sun,School,LockKeyhole,UserCog,History,Target,FileText,Send,UserRound,Info,Filter} from 'lucide-react';
import {ResponsiveContainer,BarChart,Bar,CartesianGrid,XAxis,YAxis,Tooltip,Legend,PieChart,Pie,Cell,LineChart,Line} from 'recharts';
import {api,setCsrf} from './api';
import './styles.css';

type Any=Record<string,any>;
const Ctx=createContext<any>(null);
function useApp(){return useContext(Ctx)}
const groups:Record<string,{title:string;items:[string,string,any][]}[]>={
 admin:[
  {title:'Overview',items:[['overview','Command Center',LayoutDashboard],['students','Student Directory',GraduationCap],['analytics','Student Analytics',ChartNoAxesCombined],['ml','Machine Learning',BrainCircuit]]},
  {title:'College Management',items:[['faculty','Faculty & Users',Users],['assignments','Teaching Assignments',BookOpen],['attendance','Attendance',ClipboardCheck],['marks','Marks & Publishing',FileSpreadsheet],['timetable','Timetable',CalendarDays]]},
  {title:'Support & Communication',items:[['interventions','Interventions',Target],['requests','Student Requests',MessageSquare],['notices','Announcements',Bell]]},
  {title:'Administration',items:[['import','Supabase Import',Database],['connectors','External Data Sources',Link2],['audit','Activity & Audit',History],['security','Account & Security',Settings]]}
 ],
 faculty:[
  {title:'My Teaching',items:[['overview','Faculty Dashboard',LayoutDashboard],['students','My Students',Users],['assignments','My Classes',BookOpen],['attendance','Take Attendance',ClipboardCheck],['marks','Enter & Publish Marks',FileSpreadsheet],['timetable','Timetable',CalendarDays]]},
  {title:'Support',items:[['analytics','Class Analytics',ChartNoAxesCombined],['ml','ML Risk Insights',BrainCircuit],['interventions','Mentoring & Intervention',Target],['requests','Student Requests',MessageSquare],['notices','Announcements',Bell],['security','My Account',Settings]]}
 ],
 student:[
  {title:'My Success',items:[['overview','Student Dashboard',LayoutDashboard],['profile','My Profile',UserRound],['analytics','Success Insights',ChartNoAxesCombined],['ml','ML Risk Insights',BrainCircuit]]},
  {title:'Academics',items:[['attendance','My Attendance',ClipboardCheck],['marks','My Marks & Results',FileSpreadsheet],['timetable','My Timetable',CalendarDays]]},
  {title:'Support',items:[['interventions','My Support Plans',Target],['requests','My Requests',MessageSquare],['notices','Announcements',Bell],['security','My Account',Settings]]}
 ]};
const dateToday=new Date().toLocaleDateString('en-CA');
const fmt=(n:any,decimal=1)=>n===null||n===undefined||n===''?'Not recorded':Number(n).toFixed(decimal);
const lab=(x:any)=>x===null||x===undefined||x===''?'—':String(x);
const errMsg=(e:any)=>e instanceof Error?e.message:String(e);
const riskOf=(x:any)=>x==='Support needed'?'High':x==='Undetermined'?'Unknown':'Low';
const riskClass=(s:string)=>s==='High'?'high':s==='Medium'?'med':s==='Low'?'low':'plain';
function Tag({children,kind='plain'}:{children:React.ReactNode;kind?:string}){return <span className={'pill '+kind}>{children}</span>}
function IconButton({children,onClick,title}:any){return <button className="iconbtn" onClick={onClick} title={title}>{children}</button>}
function downloadCsv(filename:string,cols:string[],rows:any[][]){const escape=(v:any)=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv=[cols.map(escape).join(','),...rows.map(r=>r.map(escape).join(','))].join('\r\n');const b=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=filename;a.click();URL.revokeObjectURL(a.href)}
function StatusLine({children,error=false}:any){return <p className={error?'err':'hint'} role={error?'alert':undefined}>{children}</p>}
function Panel({title,sub,children,action}:any){return <section className="card"><div className="card-h"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>{children}</section>}
function PageHeader({code,title,sub,action}:any){return <div className="ph"><div><span className="tag">{code}</span><h1>{title}</h1>{sub&&<p>{sub}</p>}</div><div className="row">{action}</div></div>}
function Kpi({title,value,subtitle,kind}:any){return <div className="card kpi"><span className="k">{title}</span><span className={'v '+(kind||'')}>{value}</span><span className="s">{subtitle}</span></div>}
function Empty({children}:any){return <div className="empty">{children}</div>}
function FormField({label,children}:any){return <label className="fld"><span className="lbl">{label}</span>{children}</label>}
function Select({value,onChange,options}:any){return <select className="sel" value={value} onChange={e=>onChange(e.target.value)}>{options.map((o:any)=><option key={typeof o==='string'?o:o.value} value={typeof o==='string'?o:o.value}>{typeof o==='string'?o:o.label}</option>)}</select>}
function SearchInput({value,onChange,placeholder='Search students, IDs, departments...'}:any){return <div className="sinput"><Search size={17}/><input className="inp" value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></div>}
function Dialog({title,children,onClose}:any){return <div className="scrim mid" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal wide"><div className="row spread"><h2 style={{fontSize:21}}>{title}</h2><IconButton onClick={onClose}><X size={18}/></IconButton></div><div style={{marginTop:16}}>{children}</div></div></div>}
function WorkingForm({fields,submit,initial={},button='Save'}:any){const [data,setData]=useState<Any>(initial),[busy,setBusy]=useState(false),[error,setError]=useState('');async function save(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{await submit(data)}catch(e){setError(errMsg(e))}finally{setBusy(false)}}return <form className="stack" onSubmit={save}>{fields.map((f:any)=><FormField label={f.label} key={f.key}>{f.options?<Select value={String(data[f.key]??f.options[0]?.value??f.options[0]??'')} onChange={(v:any)=>setData(d=>({...d,[f.key]:v}))} options={f.options}/>:f.type==='textarea'?<textarea className="txt" required={f.required!==false} value={data[f.key]??''} onChange={e=>setData(d=>({...d,[f.key]:e.target.value}))}/>:<input className="inp" type={f.type||'text'} required={f.required!==false} min={f.min} max={f.max} minLength={f.minLength} value={data[f.key]??''} placeholder={f.placeholder||''} onChange={e=>setData(d=>({...d,[f.key]:e.target.value}))}/>}</FormField>)}{error&&<StatusLine error>{error}</StatusLine>}<button className="btn primary" disabled={busy} type="submit">{busy?'Saving…':button}</button></form>}
function useRemote<T=any>(path:string,depend:any[]=[]){const [data,setData]=useState<T|null>(null),[busy,setBusy]=useState(true),[error,setError]=useState(''),[version,setVersion]=useState(0);useEffect(()=>{let active=true;setBusy(true);setError('');api<T>(path).then(d=>{if(active)setData(d)}).catch(e=>{if(active)setError(errMsg(e))}).finally(()=>{if(active)setBusy(false)});return()=>{active=false}},[path,version,...depend]);return {data,busy,error,refresh:()=>setVersion(v=>v+1)}}
function Loading(){return <div className="empty"><span className="spin"/> Loading actual college records…</div>}
function ErrorText({error,refresh}:any){return <div className="callout bad"><b>Unable to load this section.</b><p>{error}</p><button className="btn sm" onClick={refresh}><RefreshCw size={14}/> Retry</button></div>}
function App(){const [session,setSession]=useState<any>(null),[checking,setChecking]=useState(true),[view,setView]=useState('overview'),[menu,setMenu]=useState(false),[drawer,setDrawer]=useState(''),[error,setError]=useState(''),[theme,setTheme]=useState(localStorage.getItem('piq-theme')||'light'),[nonce,setNonce]=useState(0);useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('piq-theme',theme)},[theme]);useEffect(()=>{api('/auth/me').then(data=>{setCsrf(data.csrf_token);setSession(data.user)}).catch(()=>{}).finally(()=>setChecking(false))},[]);useEffect(()=>{const fn=()=>{setSession(null);setCsrf('')};window.addEventListener('session-expired',fn);return()=>window.removeEventListener('session-expired',fn)},[]);
const run=async(fn:()=>Promise<any>,message='Saved successfully')=>{setError('');try{const result=await fn();setNonce(v=>v+1);setDrawer('');return result}catch(e){setError(errMsg(e));throw e}};
const go=(v:string)=>{setView(v);setMenu(false);setDrawer('');setError('')};async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}setSession(null);setCsrf('');setView('overview')}
if(checking)return <div className="welc"><Activity className="pulse" size={36}/><p>Connecting to PULSEIQ…</p></div>;
if(!session)return <Login onLogin={(d:any)=>{setCsrf(d.csrf_token);setSession(d.user);setView('overview')}} theme={theme} toggle={()=>setTheme(theme==='dark'?'light':'dark')}/>;
const user=session,nav=groups[user.role]||[];const all=nav.flatMap(g=>g.items);const current=all.find(i=>i[0]===view)?.[1]||'PulseIQ';return <Ctx.Provider value={{user,go,nonce,run,openStudent:setDrawer,setError}}><div className={'app '+(menu?'nav-open':'')}><div className="navscrim" onClick={()=>setMenu(false)}/><aside className="side"><div className="brand"><div className="logo-mini"><Activity size={20}/></div>Pulse<span>IQ</span></div><div className="rolechip"><b>{user.college_name||'College'}</b>{user.role==='admin'?'College Administrator':user.role==='faculty'?'Faculty Portal':'Student Portal'}</div>{nav.map(g=><div key={g.title}><p className="ng">{g.title}</p>{g.items.map(([id,title,Icon]:any)=><button key={id} className={'nl '+(view===id?'on':'')} onClick={()=>go(id)}><Icon size={17}/><span>{title}</span></button>)}</div>)}<div className="side-foot"><button className="nl" onClick={logout}><LogOut size={17}/> Sign out</button></div></aside><main className="main"><header className="top"><IconButton onClick={()=>setMenu(!menu)}><Menu size={18}/></IconButton><strong className="ttl">{current}</strong><div className="topright"><span className="auth-user"><span className="av">{user.full_name?.split(' ').map((s:string)=>s[0]).slice(0,2).join('')}</span><span><b>{user.full_name}</b><small>{user.role}</small></span></span><IconButton title="Theme" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={17}/>:<Moon size={17}/>}</IconButton></div></header><div className="page">{error&&<div className="callout bad" role="alert"><div className="row spread"><span>{error}</span><button className="btn sm" onClick={()=>setError('')}>Dismiss</button></div></div>}
{view==='overview'&&<Dashboard/>}{(view==='students'||view==='profile')&&<StudentsPage profile={view==='profile'}/>}{view==='analytics'&&<AnalyticsPage/>}{view==='ml'&&<MLPage/>}{view==='faculty'&&<UsersPage/>}{view==='assignments'&&<AssignmentsPage/>}{(view==='attendance'||view==='marks')&&<EntriesPage kind={view}/>}{view==='interventions'&&<InterventionsPage/>}{view==='timetable'&&<TimetablePage/>}{view==='requests'&&<RequestsPage/>}{view==='notices'&&<NoticesPage/>}{view==='import'&&<ImportPage/>}{view==='connectors'&&<ConnectorsPage/>}{view==='audit'&&<AuditPage/>}{view==='security'&&<SecurityPage/>}
<footer className="foot">PULSEIQ · College-isolated records · ML indicators are decision-support, not definitive student outcomes.</footer></div></main>{drawer&&<StudentDrawer studentId={drawer} onClose={()=>setDrawer('')}/>}</div></Ctx.Provider>}
function Login({onLogin,theme,toggle}:any){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);const [college,setCollege]=useState('');useEffect(()=>{const h=setTimeout(()=>{if(email.includes('@'))api('/colleges/resolve?email='+encodeURIComponent(email)).then((d:any)=>setCollege(d.recognized?d.college_name:'')).catch(()=>setCollege(''));else setCollege('')},450);return()=>clearTimeout(h)},[email]);async function submit(e:any){e.preventDefault();setBusy(true);setError('');try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({email,password})});onLogin(d)}catch(e){setError(errMsg(e))}finally{setBusy(false)}}return <div className="auth"><section className="auth-l"><div className="brand"><div className="logo-mini"><Activity/></div>PulseIQ</div><div><span className="pill acc plain">SMART CAMPUS INTELLIGENCE</span><h2 style={{marginTop:12}}>Help every student find their path to success.</h2><p style={{marginTop:14}}>Attendance. Academics. AI insights. One unified college workspace.</p><svg viewBox="0 0 600 80" className="ecg"><path d="M0 40h130l12-8 10 8h40l10-6 8 6h30l12-26 14 50 12-24h26l10-8 10 8h90l14-8 10 8h40l12-20 12 36 12-16h60"/></svg></div><p className="hint">Administrator · Faculty · Student</p></section><section className="auth-r"><form onSubmit={submit} className="auth-card"><div className="row spread"><div className="logo"><Activity/></div><IconButton onClick={toggle}>{theme==='dark'?<Sun size={19}/>:<Moon size={19}/>}</IconButton></div><h1>Welcome back.</h1><p className="muted">Sign in with your registered college account.</p>{college?<div className="det"><CheckCircle2 size={18}/>{college} recognised</div>:email.includes('@')?<div className="det no"><Info size={18}/>Ensure your account belongs to the configured college.</div>:null}<FormField label="Institutional email"><input className="inp" type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} placeholder="admin@demo.edu.in" required/></FormField><FormField label="Password"><input className="inp" type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></FormField>{error&&<StatusLine error>{error}</StatusLine>}<button className="btn primary" disabled={busy} type="submit">{busy?'Signing in…':'Sign in securely'} <ChevronRight size={17}/></button><p className="hint">Accounts are created by your college administrator. Demo login addresses and passwords depend on the import or bootstrap configuration; this screen does not invent credentials.</p></form></section></div>}
function Dashboard(){const {user,go,openStudent,nonce}=useApp();const students=useRemote<any>('/students',[nonce]);const stats=useRemote<any>('/analytics',[nonce]);const actions=useRemote<any>('/actions',[nonce]);const roster=students.data?.items||[];const scores=stats.data?.items||[];const supports=scores.filter((x:any)=>x.academic_flag==='Support needed'||x.placement_flag==='Support needed');const scored=scores.filter((x:any)=>x.overall_score!=null);const departments=Object.entries(roster.reduce((a:Any,x:any)=>({...a,[x.department]:(a[x.department]||0)+1}),{})).map(([name,count])=>({name,count}));const bars=[{name:'Support needed',value:supports.length},{name:'No observed flags',value:scores.filter((x:any)=>x.academic_flag==='No observed trigger'&&x.placement_flag==='No observed trigger').length},{name:'Incomplete evidence',value:scores.filter((x:any)=>x.score_status==='Insufficient data').length}];return <><PageHeader code="CAMPUS INTELLIGENCE" title={user.role==='student'?'Your success, clearly understood.':user.role==='faculty'?'Your classes at a glance.':'The college pulse at a glance.'} sub={`Live records for ${user.college_name||'your college'} · This dashboard never fabricates missing academic data.`} action={<button className="btn" onClick={()=>go('analytics')}><ChartNoAxesCombined size={16}/> Explore analytics</button>}/>{students.busy||stats.busy?<Loading/>:students.error||stats.error?<ErrorText error={students.error||stats.error} refresh={()=>{students.refresh();stats.refresh()}}/>:<><div className="grid g4"><Kpi title={user.role==='student'?'Your profile':'Visible students'} value={roster.length} subtitle={user.role==='faculty'?'Assigned class roster':user.role==='student'?'Your own student record':'Live college roster'}/><Kpi title="Need intervention" value={supports.length} subtitle="Evidence-based rules" kind={supports.length?'dn':''}/><Kpi title="Scored students" value={scored.length} subtitle={`${scores.length-scored.length} without enough observations`}/><Kpi title="Average success score" value={scored.length?fmt(scored.reduce((a:number,x:any)=>a+x.overall_score,0)/scored.length):'N/A'} subtitle="Measured records only"/></div><div className="grid g-main"><Panel title="Department enrolment" sub="Counts are calculated from your Supabase-backed roster"><div className="chartbox"><ResponsiveContainer width="100%" height="100%"><BarChart data={departments}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis allowDecimals={false}/><Tooltip/><Bar fill="var(--accent)" dataKey="count" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div>{!departments.length&&<Empty>No student records yet. Admin: import your Supabase tables.</Empty>}</Panel><Panel title="Student support coverage" sub="Rules detect observed triggers; incomplete data remains incomplete"><div className="chartbox"><ResponsiveContainer width="100%" height="100%"><BarChart layout="vertical" data={bars}><CartesianGrid strokeDasharray="3 3"/><XAxis type="number" allowDecimals={false}/><YAxis type="category" dataKey="name" width={120}/><Tooltip/><Bar dataKey="value" fill="var(--accent)" radius={[0,5,5,0]}/></BarChart></ResponsiveContainer></div></Panel></div><Panel title="Students requiring attention" sub="Open the profile for reasons, published records and follow-up actions" action={<button className="btn sm" onClick={()=>go('students')}>All students <ChevronRight size={15}/></button>}><div className="tw"><table><thead><tr><th>Student</th><th>Department</th><th>Academic</th><th>Placement</th><th>Score</th></tr></thead><tbody>{supports.slice(0,10).map((x:any)=><tr className="clk" key={x.student_id} onClick={()=>openStudent(x.student_id)}><td><b>{x.full_name}</b><div className="sub mono">{x.student_id}</div></td><td>{x.department} · Sem {x.semester}</td><td><Tag kind="high">{riskOf(x.academic_flag)}</Tag></td><td><Tag kind={riskClass(riskOf(x.placement_flag))}>{riskOf(x.placement_flag)}</Tag></td><td>{lab(x.overall_score)}</td></tr>)}</tbody></table>{!supports.length&&<Empty>No observed support triggers in the visible records.</Empty>}</div></Panel><Panel title="Current interventions" sub="All records are stored in the application database" action={<button className="btn sm" onClick={()=>go('interventions')}>Manage plans</button>}><div className="row spread"><span><b>{actions.data?.items?.length||0}</b> documented intervention plans</span><span className="hint">Not simulated</span></div></Panel></>}</>}
function StudentsPage({profile=false}:any){const {user,openStudent,nonce,run}=useApp();const roster=useRemote<any>('/students',[nonce]);const [q,setQ]=useState(''),[dept,setDept]=useState('All'),[page,setPage]=useState(0),[adding,setAdding]=useState(false),[editing,setEditing]=useState<any>(null);const list=roster.data?.items||[];const depts=['All',...new Set<string>(list.map((x:any)=>x.department))];const filtered=list.filter((x:any)=>(dept==='All'||x.department===dept)&&[x.student_id,x.full_name,x.department,x.section].join(' ').toLowerCase().includes(q.toLowerCase()));useEffect(()=>setPage(0),[q,dept]);const paged=filtered.slice(page*25,(page+1)*25);return <><PageHeader code="STUDENT SUCCESS" title={profile?'My Student Profile':'Student Directory'} sub={user.role==='admin'?'All students in your PULSEIQ roster, including imported Supabase records.':'Only student records you are permitted to view.'} action={<>{user.role==='admin'&&<button className="btn primary" onClick={()=>setAdding(true)}><Plus size={16}/> Add student</button>}<button className="btn" onClick={()=>downloadCsv('pulseiq_students.csv',['Roll','Name','Email','Department','Semester','Section'],filtered.map((s:any)=>[s.student_id,s.full_name,s.email,s.department,s.semester,s.section]))}><Download size={16}/> Export CSV</button></>}/>{roster.busy?<Loading/>:roster.error?<ErrorText error={roster.error} refresh={roster.refresh}/>:<Panel title={`Students (${filtered.length})`} sub="Search, filter, open student details and view published assessments"><div className="toolbar" style={{marginBottom:14}}><div className="grow"><SearchInput value={q} onChange={setQ}/></div><FormField label="Department"><Select value={dept} onChange={setDept} options={depts}/></FormField><button className="btn" onClick={roster.refresh}><RefreshCw size={16}/> Refresh</button></div><div className="tw"><table><thead><tr><th>Roll number</th><th>Name</th><th>Department</th><th>Semester</th><th>Section</th><th>Email</th><th>Action</th></tr></thead><tbody>{paged.map((s:any)=><tr key={s.id}><td className="mono">{s.student_id}</td><td><b>{s.full_name}</b></td><td>{s.department}</td><td>{s.semester}</td><td>{s.section}</td><td>{s.email||'—'}</td><td><div className="row"><button className="btn sm" onClick={()=>openStudent(s.student_id)}>View <ChevronRight size={14}/></button>{user.role==='admin'&&<button className="btn sm" onClick={()=>{setEditing(s);setAdding(true)}}>Edit</button>}</div></td></tr>)}</tbody></table>{!paged.length&&<Empty>No matching students. {user.role==='admin'?'Use Supabase Import if your roster is empty.':'Ask the administrator to check your class assignments.'}</Empty>}</div><div className="pager"><span className="hint">{filtered.length?`${page*25+1}–${Math.min((page+1)*25,filtered.length)} of ${filtered.length}`:'0 records'}</span><div className="row"><button className="btn sm" disabled={!page} onClick={()=>setPage(p=>p-1)}>Previous</button><button className="btn sm" disabled={(page+1)*25>=filtered.length} onClick={()=>setPage(p=>p+1)}>Next</button></div></div></Panel>}{adding&&<Dialog title={editing?"Edit student":"Add student"} onClose={()=>{setAdding(false);setEditing(null)}}><WorkingForm fields={[{key:'student_id',label:'Student roll number'},{key:'full_name',label:'Full name'},{key:'email',label:'College email',type:'email',required:false},{key:'department',label:'Department'},{key:'semester',label:'Semester',type:'number',min:1,max:12},{key:'section',label:'Section'}]} initial={editing?{...editing,email:editing.email||''}:{semester:1,section:'A'}} submit={async(d:any)=>{await run(()=>api('/admin/students',{method:'POST',body:JSON.stringify({...d,semester:+d.semester,email:d.email||null})}));setAdding(false);setEditing(null);roster.refresh()}}/></Dialog>}</>}
function StudentDrawer({studentId,onClose}:any){const {user,go}=useApp();const detail=useRemote<any>('/students/'+encodeURIComponent(studentId));const x=detail.data?.record||{};return <div className="scrim" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><aside className="drawer" style={{width:'min(700px,100%)'}}><div className="row spread"><div><span className="tag">STUDENT 360°</span><h2 style={{marginTop:8}}>{detail.data?.record?.full_name||studentId}</h2><span className="muted mono">{studentId}</span></div><IconButton onClick={onClose}><X size={18}/></IconButton></div>{detail.busy?<Loading/>:detail.error?<ErrorText error={detail.error} refresh={detail.refresh}/>:<><div className="grid g3"><Kpi title="Score" value={lab(x.overall_score)} subtitle={x.score_status||'Unscored'}/><Kpi title="Attendance" value={x.classes_held?fmt(100*x.classes_attended/x.classes_held)+'%':'N/A'} subtitle="Published classes"/><Kpi title="Marks" value={x.marks_pct!=null?fmt(x.marks_pct)+'%':'N/A'} subtitle="Published assessments"/></div><Panel title="Student details"><div className="grid g2"><div><span className="lbl">Department</span><p>{x.department}</p></div><div><span className="lbl">Semester / Section</span><p>{x.semester} / {x.section}</p></div><div><span className="lbl">Academic support</span><p><Tag kind={riskClass(riskOf(x.academic_flag))}>{x.academic_flag}</Tag></p></div><div><span className="lbl">Placement support</span><p><Tag kind={riskClass(riskOf(x.placement_flag))}>{x.placement_flag}</Tag></p></div></div></Panel><Panel title="Observed evidence" sub="Scores exclude missing or stale source data"><div className="stack">{(detail.data?.components||[]).map((c:any,i:number)=><div className="row spread" key={i}><span>{c.component||c.label||c.name||'Component'}</span><b>{lab(c.value??c.score)}</b></div>)}{!(detail.data?.components||[]).length&&<Empty>No component observations yet.</Empty>}</div></Panel><Panel title="Recommended actions" sub="Derived from observed indicators"><div className="stack">{(x.recommendations||[]).map((r:any,i:number)=><div className="callout" key={i}>{r.action}</div>)}{!(x.recommendations||[]).length&&<Empty>No recommendations without observed triggers.</Empty>}</div></Panel><WhatIf studentId={studentId} record={x}/><Panel title="Published faculty records"><div className="tw"><table><thead><tr><th>Subject</th><th>Type</th><th>Date</th><th>Value</th></tr></thead><tbody>{(detail.data?.faculty_records||[]).map((r:any)=><tr key={r.id}><td>{r.subject}</td><td>{r.kind}</td><td>{r.period_end}</td><td>{r.kind==='attendance'?`${r.attended}/${r.held}`:`${r.marks_pct}%`}</td></tr>)}</tbody></table>{!detail.data?.faculty_records?.length&&<Empty>No published subject records yet.</Empty>}</div></Panel>{user.role!=='student'&&<button className="btn primary" onClick={()=>{onClose();go('interventions')}}>Open support plans</button>}</>}</aside></div>}
function WhatIf({studentId,record}:any){const [marks,setMarks]=useState(''),[attended,setAttended]=useState(''),[out,setOut]=useState<any>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);const hasMarks=record.marks_pct!==null&&record.marks_pct!==undefined&&record.academic__fresh;const hasAttendance=record.classes_attended!==null&&record.classes_attended!==undefined&&record.attendance__fresh;async function simulate(){setBusy(true);setError('');setOut(null);try{const changes:Any={};if(hasMarks&&marks!=='')changes.marks_pct=Number(marks);if(hasAttendance&&attended!=='')changes.classes_attended=Number(attended);if(!Object.keys(changes).length)throw new Error('Enter at least one observed value to simulate.');const result=await api('/students/'+encodeURIComponent(studentId)+'/scenario',{method:'POST',body:JSON.stringify({changes})});setOut(result)}catch(e){setError(errMsg(e))}finally{setBusy(false)}}return <Panel title="What-if scenario" sub="Simulate improvements without changing your student database."><div className="grid g2"><FormField label="Hypothetical marks %"><input className="inp" type="number" min="0" max="100" value={marks} disabled={!hasMarks} placeholder={hasMarks?String(record.marks_pct):'No fresh marks observed'} onChange={e=>setMarks(e.target.value)}/></FormField><FormField label="Hypothetical sessions attended"><input className="inp" type="number" min="0" max={record.classes_held||0} value={attended} disabled={!hasAttendance} placeholder={hasAttendance?String(record.classes_attended):'No fresh attendance observed'} onChange={e=>setAttended(e.target.value)}/></FormField></div><button className="btn sm primary" style={{marginTop:12}} onClick={simulate} disabled={busy||(!hasMarks&&!hasAttendance)}><ChartNoAxesCombined size={16}/> {busy?'Calculating…':'Run what-if'}</button>{error&&<StatusLine error>{error}</StatusLine>}{out&&<div className="callout" style={{marginTop:12}}><b>Scenario result (hypothetical only)</b><pre className="mono" style={{fontSize:11,whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{JSON.stringify(out.scenario,null,2)}</pre>{out.notice&&<p className="hint">{out.notice}</p>}</div>}</Panel>}
function AnalyticsPage(){const {openStudent,nonce}=useApp();const a=useRemote<any>('/analytics',[nonce]);const [department,setDepartment]=useState('All'),[q,setQ]=useState('');const rows=a.data?.items||[];const depts=['All',...new Set<string>(rows.map((x:any)=>x.department))];const visible=rows.filter((r:any)=>(department==='All'||r.department===department)&&[r.student_id,r.full_name].join(' ').toLowerCase().includes(q.toLowerCase()));const scored=visible.filter((s:any)=>s.overall_score!=null);const bands=[{name:'Academic support',n:visible.filter((s:any)=>s.academic_flag==='Support needed').length},{name:'Placement support',n:visible.filter((s:any)=>s.placement_flag==='Support needed').length},{name:'Insufficient data',n:visible.filter((s:any)=>s.score_status==='Insufficient data').length}];const byDept=depts.filter(x=>x!=='All').map(d=>{const x=rows.filter((r:any)=>r.department===d),s=x.filter((y:any)=>y.overall_score!=null);return {department:d,students:x.length,score:s.length?Math.round(s.reduce((v:number,y:any)=>v+y.overall_score,0)/s.length):null}});return <><PageHeader code="RISK & SUCCESS ANALYTICS" title="Evidence before prediction." sub="Rule-based academic and placement indicators from live published and imported records. Missing evidence is not interpreted as success or failure." action={<button className="btn" onClick={()=>downloadCsv('analytics.csv',['Roll','Name','Department','Score','Coverage','Academic flag','Placement flag'],visible.map((r:any)=>[r.student_id,r.full_name,r.department,r.overall_score,r.coverage,r.academic_flag,r.placement_flag]))}><Download size={16}/> Export</button>}/>{a.busy?<Loading/>:a.error?<ErrorText error={a.error} refresh={a.refresh}/>:<><div className="grid g4"><Kpi title="Included students" value={visible.length} subtitle="Scope and selected filters"/><Kpi title="Valid success scores" value={scored.length} subtitle="Based on real observations"/><Kpi title="Academic support" value={bands[0].n} subtitle="Observed threshold breaches"/><Kpi title="Placement support" value={bands[1].n} subtitle="Observed readiness gaps"/></div><div className="grid g2"><Panel title="Risk distribution" sub="Rule indicators, not model probabilities"><div className="chartbox"><ResponsiveContainer width="100%" height="100%"><BarChart data={bands}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="name"/><YAxis allowDecimals={false}/><Tooltip/><Bar dataKey="n" fill="var(--accent)" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></div></Panel><Panel title="Department score comparison" sub="Departments without scores are not plotted"><div className="chartbox"><ResponsiveContainer width="100%" height="100%"><BarChart data={byDept}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="department"/><YAxis domain={[0,100]}/><Tooltip/><Bar dataKey="score" fill="var(--c2)"/></BarChart></ResponsiveContainer></div></Panel></div><Panel title="Explore every student" sub={`${visible.length} records; click a student to inspect evidence`}><div className="toolbar" style={{marginBottom:12}}><div className="grow"><SearchInput value={q} onChange={setQ}/></div><FormField label="Department"><Select value={department} onChange={setDepartment} options={depts}/></FormField></div><div className="tw"><table><thead><tr><th>Student</th><th>Department</th><th>Score</th><th>Evidence coverage</th><th>Academics</th><th>Placement</th></tr></thead><tbody>{visible.slice(0,500).map((r:any)=><tr className="clk" key={r.student_id} onClick={()=>openStudent(r.student_id)}><td><b>{r.full_name}</b><div className="sub mono">{r.student_id}</div></td><td>{r.department}</td><td>{lab(r.overall_score)}</td><td>{r.coverage!=null?Math.round(r.coverage*100)+'%':'—'}</td><td><Tag kind={riskClass(riskOf(r.academic_flag))}>{r.academic_flag}</Tag></td><td><Tag kind={riskClass(riskOf(r.placement_flag))}>{r.placement_flag}</Tag></td></tr>)}</tbody></table>{!visible.length&&<Empty>No students match these filters.</Empty>}</div></Panel></>}</>}
function MLPage(){const {user,nonce,run,openStudent}=useApp();const status=useRemote<any>('/ml/status',[nonce]);const pred=useRemote<any>('/ml/predictions',[nonce]);const [modelBusy,setModelBusy]=useState(false);const [error,setError]=useState('');const [form,setForm]=useState(false);async function train(demo:boolean){setModelBusy(true);setError('');try{await run(()=>api('/admin/ml/train',{method:'POST',body:JSON.stringify({demo})}));status.refresh();pred.refresh()}catch(e){setError(errMsg(e))}finally{setModelBusy(false)}}const model=status.data?.model;return <><PageHeader code="TRADITIONAL MACHINE LEARNING" title="Random Forest Risk Model" sub="Supervised classification with a held-out test set. Distinct from the rules engine: no labeled outcomes means no real-world trained model."/>{status.busy?<Loading/>:status.error?<ErrorText error={status.error} refresh={status.refresh}/>:<><div className="grid g4"><Kpi title="Training status" value={status.data?.trained?'Trained':'Not trained'} subtitle={model?.metadata?.source==='synthetic_demo'?'Synthetic DEMO only':model?.metadata?.source==='historical_labeled'?'Historical labels':'Awaiting training examples'}/><Kpi title="Labeled examples" value={status.data?.labeled_examples??0} subtitle="40 minimum for real model"/><Kpi title="ROC–AUC" value={model?.metadata?.metrics?.roc_auc??'N/A'} subtitle="Holdout evaluation"/><Kpi title="Test examples" value={model?.metadata?.metrics?.test_count??'—'} subtitle="Test split excluded from training"/></div>{model?.metadata?.source==='synthetic_demo'&&<div className="callout warn"><strong>Demo model only.</strong> Trained with reproducible synthetic examples. Its probabilities are for showing the interface and must not be treated as validated real student outcome predictions.</div>}{user.role==='admin'&&<Panel title="Training controls" sub="Choose an explicitly simulated demo model or add retrospective labeled training examples."><div className="row"><button className="btn primary" disabled={modelBusy} onClick={()=>train(false)}><BrainCircuit size={16}/> Train with historical examples</button><button className="btn" disabled={modelBusy} onClick={()=>train(true)}>Train synthetic demo model</button><button className="btn" onClick={()=>setForm(true)}><Plus size={16}/> Add labeled example</button></div>{error&&<StatusLine error>{error}</StatusLine>}<p className="hint" style={{marginTop:10}}>For real training, each historical feature snapshot must precede its labeled later outcome. Do not train on the same data used to define the label.</p></Panel>}{model&&<Panel title="Model performance & feature importance" sub="Measured on a held-out portion of training data"><div className="grid g2"><div className="stack">{Object.entries(model.metadata?.metrics||{}).map(([key,value])=><div className="row spread" key={key}><span>{key.replace(/_/g,' ')}</span><b className="mono">{String(value)}</b></div>)}</div><div className="chartbox"><ResponsiveContainer width="100%" height="100%"><BarChart layout="vertical" data={model.metadata?.feature_importance||[]}><CartesianGrid strokeDasharray="3 3"/><XAxis type="number"/><YAxis dataKey="feature" type="category" width={105}/><Tooltip/><Bar fill="var(--accent)" dataKey="importance"/></BarChart></ResponsiveContainer></div></div></Panel>}<Panel title="Individual ML risk outputs" sub="Available only when a model is trained and at least two current features are observed">{pred.busy?<Loading/>:pred.error?<ErrorText error={pred.error} refresh={pred.refresh}/>:pred.data?.trained?<><p className="hint">{pred.data?.excluded_missing_data||0} students omitted because of insufficient observed features.</p><div className="tw"><table><thead><tr><th>Student</th><th>Risk probability</th><th>Observed features</th><th>Source</th></tr></thead><tbody>{[...(pred.data?.items||[])].sort((a:any,b:any)=>b.risk_probability-a.risk_probability).slice(0,250).map((x:any)=><tr className="clk" key={x.student_id} onClick={()=>openStudent(x.student_id)}><td>{x.full_name}<div className="sub mono">{x.student_id}</div></td><td><b>{(x.risk_probability*100).toFixed(1)}%</b></td><td>{x.observed_features} / 7</td><td><Tag kind={model?.metadata?.source==='synthetic_demo'?'med':'acc'}>{model?.metadata?.source==='synthetic_demo'?'Demo':'Historical'}</Tag></td></tr>)}</tbody></table>{!pred.data?.items?.length&&<Empty>No eligible students currently have enough observations. Add attendance/marks records first.</Empty>}</div></>:<Empty>No model trained. The rule-based student analytics remain usable.</Empty>}</Panel>{form&&<Dialog title="Add historical labeled training example" onClose={()=>setForm(false)}><WorkingForm fields={[{key:'marks_pct',label:'Historical marks percentage',type:'number',min:0,max:100},{key:'attendance_pct',label:'Historical attendance percentage',type:'number',min:0,max:100},{key:'lms_pct',label:'LMS completion %',type:'number',min:0,max:100,required:false},{key:'placement_pct',label:'Placement readiness %',type:'number',min:0,max:100,required:false},{key:'backlog_count',label:'Backlogs',type:'number',min:0,max:20,required:false},{key:'outcome',label:'Later intervention outcome (0 = no, 1 = yes)',options:[{value:'0',label:'0 — No later intervention'},{value:'1',label:'1 — Required intervention'}]}]} initial={{outcome:'0'}} submit={async(d:any)=>{const feats:Any={};for(const k of status.data.features)if(d[k]!==undefined&&d[k]!=='')feats[k]=+d[k];await run(()=>api('/admin/ml/examples',{method:'POST',body:JSON.stringify({features:feats,outcome:+d.outcome})}));status.refresh();setForm(false)}}/></Dialog>}</>}</>}
function UsersPage(){const {nonce,run}=useApp();const a=useRemote<any>('/admin/accounts',[nonce]);const [show,setShow]=useState(false),[reset,setReset]=useState<any>(null),[q,setQ]=useState('');const rows=a.data?.items||[];const filtered=rows.filter((x:any)=>[x.full_name,x.email,x.role].join(' ').toLowerCase().includes(q.toLowerCase()));return <><PageHeader code="COLLEGE MANAGEMENT" title="Faculty & User Access" sub="Create faculty or student credentials, assign roles, and disable or enable accounts." action={<button className="btn primary" onClick={()=>setShow(true)}><Plus size={16}/> Create account</button>}/>{a.busy?<Loading/>:a.error?<ErrorText error={a.error} refresh={a.refresh}/>:<Panel title={`${filtered.length} accounts`} sub={`${rows.filter((x:any)=>x.role==='faculty').length} faculty · ${rows.filter((x:any)=>x.role==='student').length} student logins · ${rows.filter((x:any)=>x.role==='admin').length} administrators`}><div className="toolbar" style={{marginBottom:12}}><div className="grow"><SearchInput value={q} onChange={setQ} placeholder="Search users and roles"/></div></div><div className="tw"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Departments / ID</th><th>Status</th><th>Action</th></tr></thead><tbody>{filtered.map((x:any)=><tr key={x.id}><td><b>{x.full_name}</b></td><td>{x.email}</td><td><Tag kind="acc">{x.role}</Tag></td><td>{x.student_id||x.departments?.join(', ')||'—'}</td><td><Tag kind={x.active?'good':'high'}>{x.active?'Active':'Disabled'}</Tag></td><td><button className="btn sm" disabled={x.id===a.data?.user?.id} onClick={async()=>{if(!confirm(`Change access for ${x.email}?`))return;try{await run(()=>api(`/admin/accounts/${x.id}/toggle`,{method:'PATCH'}));a.refresh()}catch{}}}>{x.active?'Disable':'Enable'}</button><button className="btn sm" onClick={()=>setReset(x)}>Reset password</button></td></tr>)}</tbody></table>{!filtered.length&&<Empty>No users match your search.</Empty>}</div></Panel>}{show&&<Dialog title="Create an institutional login" onClose={()=>setShow(false)}><div className="callout" style={{marginBottom:14}}>Student logins must be linked to an existing roll number. Faculty accounts can then receive teaching assignments. Passwords are hashed on the backend.</div><WorkingForm fields={[{key:'full_name',label:'Full name'},{key:'email',label:'College email',type:'email'},{key:'password',label:'Temporary password (12+ characters)',type:'password',minLength:12},{key:'role',label:'Role',options:['faculty','student','admin']},{key:'departments',label:'Departments for faculty (comma separated)',required:false},{key:'student_id',label:'Student roll number (student login only)',required:false}]} initial={{role:'faculty'}} submit={async(d:any)=>{await run(()=>api('/admin/accounts',{method:'POST',body:JSON.stringify({...d,departments:d.role==='faculty'?String(d.departments||'').split(',').map((s:string)=>s.trim()).filter(Boolean):[],student_id:d.role==='student'?d.student_id:null})}));setShow(false);a.refresh()}}/></Dialog>}{reset&&<Dialog title={'Reset password for '+reset.email} onClose={()=>setReset(null)}><WorkingForm fields={[{key:'new_password',label:'New temporary password (12+ characters)',type:'password',minLength:12}]} submit={async(d:any)=>{await run(()=>api(`/admin/accounts/${reset.id}/reset-password`,{method:'POST',body:JSON.stringify(d)}));setReset(null);alert('Password reset. Existing sessions for this account have been revoked.')}}/></Dialog>}</>}
function AssignmentsPage(){const {user,nonce,run}=useApp();const data=useRemote<any>('/assignments',[nonce]);const accts=useRemote<any>(user.role==='admin'?'/admin/accounts':'/assignments',[nonce]);const [show,setShow]=useState(false);const list=data.data?.items||[];const faculty=(accts.data?.items||[]).filter((x:any)=>x.role==='faculty'&&x.active);return <><PageHeader code="TEACHING WORKLOAD" title={user.role==='faculty'?'My Assigned Classes':'Faculty Subject Assignments'} sub="These department–semester–section assignments determine faculty visibility and permission to enter marks and attendance." action={user.role==='admin'&&<button className="btn primary" onClick={()=>setShow(true)}><Plus size={16}/> Assign subject</button>}/>{data.busy?<Loading/>:data.error?<ErrorText error={data.error} refresh={data.refresh}/>:<><div className="grid g3"><Kpi title="Teaching assignments" value={list.length} subtitle="Database records"/><Kpi title="Subjects" value={new Set(list.map((x:any)=>x.subject)).size} subtitle="Unique names"/><Kpi title="Classes" value={new Set(list.map((x:any)=>`${x.department}-${x.semester}-${x.section}`)).size} subtitle="Distinct class sections"/></div><Panel title="Assignments" sub="Faculty can only see their assigned students."><div className="tw"><table><thead><tr><th>Faculty</th><th>Subject</th><th>Department</th><th>Semester</th><th>Section</th>{user.role==='admin'&&<th>Action</th>}</tr></thead><tbody>{list.map((x:any)=><tr key={x.id}><td>{x.faculty_name}</td><td><b>{x.subject}</b></td><td>{x.department}</td><td>{x.semester}</td><td>{x.section}</td>{user.role==='admin'&&<td><button className="btn sm danger" onClick={async()=>{if(!confirm('Remove this assignment?'))return;try{await run(()=>api(`/admin/assignments/${x.id}`,{method:'DELETE'}));data.refresh()}catch{}}}>Remove</button></td>}</tr>)}</tbody></table>{!list.length&&<Empty>No assignments. The College Admin must assign a faculty member to a department, semester, and section before their students are visible.</Empty>}</div></Panel></>}{show&&<Dialog title="Create faculty teaching assignment" onClose={()=>setShow(false)}><WorkingForm initial={{faculty_id:faculty[0]?.id||'',semester:1,section:'A'}} fields={[{key:'faculty_id',label:'Faculty member',options:faculty.map((f:any)=>({label:`${f.full_name} · ${f.email}`,value:f.id}))},{key:'department',label:'Department (must match student records)'},{key:'semester',label:'Semester',type:'number',min:1,max:12},{key:'section',label:'Section (e.g., A)'},{key:'subject',label:'Subject name'}]} submit={async(d:any)=>{await run(()=>api('/admin/assignments',{method:'POST',body:JSON.stringify({...d,semester:+d.semester})}));setShow(false);data.refresh()}}/></Dialog>}</>}
function EntriesPage({kind}:any){const {user,nonce,run}=useApp();const ro=useRemote<any>('/students',[nonce]);const as=useRemote<any>(user.role==='student'?'/timetable':'/assignments',[nonce]);const en=useRemote<any>(user.role==='student'?'/students':'/entries',[nonce]);const [assignmentId,setAssignmentId]=useState(''),[date,setDate]=useState(dateToday),[records,setRecords]=useState<Any>({}),[isPublished,setPublished]=useState(false);const mode=kind==='attendance'?'attendance':'marks';const ass=as.data?.items||[];const selected=ass.find((a:any)=>a.id===assignmentId)||ass[0];const students=(ro.data?.items||[]).filter((s:any)=>selected?(s.department===selected.department&&+s.semester===+selected.semester&&s.section===selected.section):true);useEffect(()=>{setRecords({})},[assignmentId,kind]);const current=useRemote<any>(user.role==='student'&&user.student_id?'/students/'+encodeURIComponent(user.student_id):'/students',[nonce]);async function submitAll(){if(!selected)throw new Error('Select a class assignment first.');const filled=students.filter((s:any)=>records[s.student_id]!==undefined&&records[s.student_id]!=='');if(!filled.length)throw new Error('Enter values for at least one student.');const errors:any[]=[];for(const s of filled){const v=+records[s.student_id];if(!Number.isFinite(v)||v<0||v>(mode==='marks'?100:1)){errors.push(s.student_id);continue}try{await api('/entries',{method:'POST',body:JSON.stringify({student_id:s.student_id,assignment_id:selected.id,kind:mode,period_end:date,status:isPublished?'published':'draft',...(mode==='marks'?{marks_pct:v}:{attended:v,held:1})})})}catch(e){errors.push(`${s.student_id}: ${errMsg(e)}`)}}if(errors.length)throw new Error(`${errors.length} records failed. ${errors.slice(0,3).join('; ')}`);en.refresh();setRecords({});return filled.length}
return <><PageHeader code="ACADEMIC RECORDS" title={user.role==='student'?kind==='marks'?'Published Marks':'My Attendance':kind==='marks'?'Subject Marks Entry & Publication':'Attendance Register'} sub={user.role==='student'?'Only published records are visible to students.':`Enter ${mode==='marks'?'marks percentages':'Present / Absent for the selected date'} per student. Drafts are private; published records feed analytics.`}/>{user.role==='student'?<>{current.busy?<Loading/>:current.error?<ErrorText error={current.error} refresh={current.refresh}/>:<StudentPublished studentId={user.student_id} kind={mode}/>}</>:<>{as.busy||ro.busy?<Loading/>:as.error||ro.error?<ErrorText error={as.error||ro.error} refresh={()=>{as.refresh();ro.refresh()}}/>:<><Panel title="Select an assigned class"><div className="toolbar"><FormField label="Assigned subject and class"><Select value={selected?.id||''} onChange={setAssignmentId} options={ass.map((a:any)=>({label:`${a.subject} · ${a.department} / Sem ${a.semester} / ${a.section}`,value:a.id}))}/></FormField><FormField label="Reporting date"><input className="inp" type="date" max={dateToday} value={date} onChange={e=>setDate(e.target.value)}/></FormField><FormField label="Entry status"><Select value={isPublished?'published':'draft'} onChange={(v:string)=>setPublished(v==='published')} options={[{value:'draft',label:'Save draft'},{value:'published',label:'Publish to analytics & students'}]}/></FormField></div></Panel><Panel title={`${mode==='marks'?'Enter marks':'Mark attendance'} — ${students.length} students`} sub="Only enter observed values. Leave unmeasured students blank; nothing is fabricated."><div className="tw"><table><thead><tr><th>Roll number</th><th>Student</th><th>{mode==='marks'?'Marks %':'Attendance (daily)'}</th></tr></thead><tbody>{students.map((s:any)=><tr key={s.id}><td className="mono">{s.student_id}</td><td>{s.full_name}</td><td>{mode==='marks'?<input className="inp" style={{maxWidth:145}} type="number" min="0" max="100" step="1" value={records[s.student_id]??''} placeholder="Not entered" onChange={e=>setRecords(v=>({...v,[s.student_id]:e.target.value}))}/>:<select className="sel" style={{maxWidth:160}} value={records[s.student_id]??''} onChange={e=>setRecords(v=>({...v,[s.student_id]:e.target.value}))}><option value="">Not entered</option><option value="1">Present</option><option value="0">Absent</option></select>}</td></tr>)}</tbody></table>{!ass.length&&<Empty>No assigned class yet. Ask the College Admin to assign a subject.</Empty>}{ass.length&&!students.length&&<Empty>No students belong to the selected department, semester and section.</Empty>}</div><div className="row" style={{marginTop:12}}><button className="btn primary" disabled={!selected||!students.length} onClick={async()=>{try{await run(submitAll);alert('Entries saved to Supabase-backed PULSEIQ tables.')}catch{}}}><CheckCircle2 size={16}/> {isPublished?'Publish':'Save draft'} entries</button><span className="hint">You can enter values for selected students and save again later.</span></div></Panel><Panel title="Previously saved faculty entries" sub="Draft and published status are shown explicitly">{en.busy?<Loading/>:en.error?<ErrorText error={en.error} refresh={en.refresh}/>:<div className="tw"><table><thead><tr><th>Student</th><th>Subject</th><th>Type</th><th>Date</th><th>Value</th><th>Status</th><th>Publish</th></tr></thead><tbody>{(en.data?.items||[]).filter((x:any)=>x.kind===mode).map((e:any)=><tr key={e.id}><td>{e.full_name}<div className="sub mono">{e.student_id}</div></td><td>{e.subject}</td><td>{e.kind}</td><td>{e.period_end}</td><td>{mode==='marks'?e.marks_pct+'%':`${e.attended} / ${e.held}`}</td><td><Tag kind={e.status==='published'?'good':'med'}>{e.status}</Tag></td><td>{e.status==='draft'&&<button className="btn sm" onClick={async()=>{try{await run(()=>api(`/entries/${e.id}/publish`,{method:'PATCH'}));en.refresh()}catch{}}}>Publish</button>}</td></tr>)}</tbody></table>{!(en.data?.items||[]).length&&<Empty>No records submitted yet.</Empty>}</div>}</Panel></>}</>}</>}
function StudentPublished({studentId,kind}:any){const item=useRemote<any>('/students/'+encodeURIComponent(studentId));const records=(item.data?.faculty_records||[]).filter((x:any)=>x.kind===kind);return item.busy?<Loading/>:item.error?<ErrorText error={item.error} refresh={item.refresh}/>:<Panel title={`${records.length} published records`} sub="Draft assessments are intentionally hidden from the student portal."><div className="tw"><table><thead><tr><th>Subject</th><th>Date</th><th>{kind==='marks'?'Marks':'Attendance'}</th></tr></thead><tbody>{records.map((x:any)=><tr key={x.id}><td>{x.subject}</td><td>{x.period_end}</td><td>{kind==='marks'?x.marks_pct+'%':`${x.attended} / ${x.held}`}</td></tr>)}</tbody></table>{!records.length&&<Empty>No published records yet.</Empty>}</div></Panel>}
function InterventionsPage(){const {user,nonce,run,openStudent}=useApp();const list=useRemote<any>('/actions',[nonce]);const ro=useRemote<any>('/students',[nonce]);const [show,setShow]=useState(false),[editing,setEditing]=useState<any>(null);return <><PageHeader code="SUPPORT TRACKING" title={user.role==='student'?'My Support Plans':'Interventions & Mentoring'} sub="Plans, owners, deadlines and review notes are recorded in Supabase. No automatic claims of improvement." action={user.role!=='student'&&<button className="btn primary" onClick={()=>setShow(true)}><Plus size={16}/> Create intervention</button>}/>{list.busy?<Loading/>:list.error?<ErrorText error={list.error} refresh={list.refresh}/>:<><div className="grid g4">{['Planned','In progress','Reviewed','Closed'].map(s=><Kpi key={s} title={s} value={(list.data?.items||[]).filter((x:any)=>x.status===s).length} subtitle="Plans"/>)}</div><Panel title="Active and historical plans" sub="Click a student to view their 360° profile"><div className="tw"><table><thead><tr><th>Student</th><th>Action</th><th>Owner</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>{(list.data?.items||[]).map((x:any)=><tr key={x.id}><td><button className="linky" onClick={()=>openStudent(x.student_id)}>{x.full_name}</button><div className="sub mono">{x.student_id}</div></td><td>{x.action}<div className="sub">{x.note}</div></td><td>{x.owner}</td><td>{x.due_date}</td><td><Tag kind={x.status==='Closed'?'good':x.status==='Planned'?'med':'acc'}>{x.status}</Tag></td><td>{user.role!=='student'&&<button className="btn sm" onClick={()=>setEditing(x)}>Update</button>}</td></tr>)}</tbody></table>{!list.data?.items?.length&&<Empty>No intervention plans yet.</Empty>}</div></Panel></>}{show&&<Dialog title="New student intervention" onClose={()=>setShow(false)}><WorkingForm fields={[{key:'student_id',label:'Student',options:(ro.data?.items||[]).map((s:any)=>({label:`${s.student_id} · ${s.full_name}`,value:s.student_id}))},{key:'owner',label:'Responsible mentor / owner'},{key:'action',label:'Support action',type:'textarea'},{key:'due_date',label:'Due date',type:'date'},{key:'note',label:'Initial note',type:'textarea',required:false}]} initial={{student_id:ro.data?.items?.[0]?.student_id||'',due_date:dateToday,note:''}} submit={async(d:any)=>{await run(()=>api('/actions',{method:'POST',body:JSON.stringify(d)}));setShow(false);list.refresh()}}/></Dialog>}{editing&&<Dialog title="Update intervention status" onClose={()=>setEditing(null)}><WorkingForm fields={[{key:'owner',label:'Owner'},{key:'action',label:'Intervention description',type:'textarea'},{key:'due_date',label:'Due date',type:'date'},{key:'status',label:'Status',options:['Planned','In progress','Reviewed','Closed']},{key:'note',label:'Review note (required to complete)',type:'textarea'}]} initial={editing} submit={async(d:any)=>{await run(()=>api(`/actions/${editing.id}`,{method:'PATCH',body:JSON.stringify({owner:d.owner,action:d.action,due_date:d.due_date,status:d.status,note:d.note,version:editing.version})}));setEditing(null);list.refresh()}}/></Dialog>}</>}
function RequestsPage(){const {user,nonce,run}=useApp();const requests=useRemote<any>('/requests',[nonce]);const [show,setShow]=useState(false),[reply,setReply]=useState<any>(null);return <><PageHeader code="SUPPORT COMMUNICATION" title="Student Requests" sub={user.role==='student'?'Ask for academic support and track the status.':'Review and respond to requests from your authorized students.'} action={user.role==='student'&&<button className="btn primary" onClick={()=>setShow(true)}><Plus size={16}/> Create request</button>}/>{requests.busy?<Loading/>:requests.error?<ErrorText error={requests.error} refresh={requests.refresh}/>:<Panel title={`${requests.data?.items?.length||0} requests`}><div className="list">{(requests.data?.items||[]).map((x:any)=><div className="li" key={x.id}><div className="grow"><div className="row"><b>{x.subject}</b><Tag kind={x.status==='Resolved'?'good':'med'}>{x.status}</Tag></div><p className="hint">{x.full_name} · {x.student_id} · {x.created_at?.slice(0,10)}</p><p style={{marginTop:7}}>{x.detail}</p>{x.reply&&<div className="callout" style={{marginTop:8}}>Response: {x.reply}</div>}</div>{user.role!=='student'&&<button className="btn sm" onClick={()=>setReply(x)}>Reply</button>}</div>)}{!requests.data?.items?.length&&<Empty>No requests so far.</Empty>}</div></Panel>}{show&&<Dialog title="Request faculty support" onClose={()=>setShow(false)}><WorkingForm fields={[{key:'subject',label:'Subject or request topic'},{key:'detail',label:'Explain your request',type:'textarea'}]} submit={async(d:any)=>{await run(()=>api('/requests',{method:'POST',body:JSON.stringify(d)}));setShow(false);requests.refresh()}}/></Dialog>}{reply&&<Dialog title={`Respond to ${reply.full_name}`} onClose={()=>setReply(null)}><WorkingForm fields={[{key:'status',label:'Status',options:['In progress','Resolved']},{key:'reply',label:'Response',type:'textarea'}]} initial={{status:'In progress'}} submit={async(d:any)=>{await run(()=>api('/requests/'+reply.id,{method:'PATCH',body:JSON.stringify(d)}));setReply(null);requests.refresh()}}/></Dialog>}</>}
function NoticesPage(){const {user,nonce,run}=useApp();const x=useRemote<any>('/announcements',[nonce]);const [show,setShow]=useState(false);return <><PageHeader code="CAMPUS COMMUNICATION" title="Announcements" sub="Published college and department notices, backed by your database." action={user.role!=='student'&&<button className="btn primary" onClick={()=>setShow(true)}><Plus size={16}/> Post announcement</button>}/>{x.busy?<Loading/>:x.error?<ErrorText error={x.error} refresh={x.refresh}/>:<div className="grid g2">{(x.data?.items||[]).map((a:any)=><Panel key={a.id} title={a.title} sub={`Audience: ${a.audience} · ${a.created_at?.slice(0,10)}`}><p>{a.body}</p>{a.department&&<p className="hint">Department: {a.department}</p>}</Panel>)}{!x.data?.items?.length&&<div className="card"><Empty>No announcements have been published.</Empty></div>}</div>}{show&&<Dialog title="Post a campus announcement" onClose={()=>setShow(false)}><WorkingForm fields={[{key:'title',label:'Title'},{key:'body',label:'Announcement body',type:'textarea'},{key:'audience',label:'Audience',options:['all','student','faculty','department']},{key:'department',label:'Department (only for department audience)',required:false}]} initial={{audience:user.role==='faculty'?'student':'all'}} submit={async(d:any)=>{await run(()=>api('/announcements',{method:'POST',body:JSON.stringify({...d,department:d.audience==='department'?d.department:null})}));setShow(false);x.refresh()}}/></Dialog>}</>}
function TimetablePage(){const {user,nonce,run}=useApp();const x=useRemote<any>('/timetable',[nonce]);const a=useRemote<any>(user.role==='student'?'/timetable':'/assignments',[nonce]);const [show,setShow]=useState(false);const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];return <><PageHeader code="ACADEMIC SCHEDULE" title="Class Timetable" sub="Subject sessions scheduled against actual teaching assignments." action={user.role!=='student'&&<button className="btn primary" onClick={()=>setShow(true)}><Plus size={16}/> Schedule class</button>}/>{x.busy?<Loading/>:x.error?<ErrorText error={x.error} refresh={x.refresh}/>:<div className="grid g2">{days.map((day,i)=><Panel title={day} key={day}><div className="stack">{(x.data?.items||[]).filter((a:any)=>a.weekday===i).map((a:any)=><div className="classslot" key={a.id}><span className="mono">{a.start_time}–{a.end_time}</span><div><b>{a.subject}</b><p className="hint">{a.department} · Sem {a.semester} · Sec {a.section} · {a.room} · {a.faculty_name}</p></div></div>)}{!(x.data?.items||[]).some((a:any)=>a.weekday===i)&&<span className="hint">No scheduled class</span>}</div></Panel>)}</div>}{show&&<Dialog title="Schedule subject session" onClose={()=>setShow(false)}><WorkingForm initial={{assignment_id:a.data?.items?.[0]?.id||'',weekday:0,start_time:'09:00',end_time:'10:00',room:'Room 101'}} fields={[{key:'assignment_id',label:'Teaching assignment',options:(a.data?.items||[]).map((z:any)=>({label:`${z.subject} · ${z.department} Sem ${z.semester} ${z.section}`,value:z.id}))},{key:'weekday',label:'Weekday',options:days.map((d,i)=>({value:String(i),label:d}))},{key:'start_time',label:'Start time',type:'time'},{key:'end_time',label:'End time',type:'time'},{key:'room',label:'Room'}]} submit={async(d:any)=>{await run(()=>api('/timetable',{method:'POST',body:JSON.stringify({...d,weekday:+d.weekday})}));setShow(false);x.refresh()}}/></Dialog>}</>}
function ImportPage(){const {nonce,run}=useApp();const [facultyPassword,setFacultyPassword]=useState(''),[studentPassword,setStudentPassword]=useState(''),[busy,setBusy]=useState(false),[stats,setStats]=useState<any>(null),[error,setError]=useState('');const students=useRemote<any>('/students',[nonce]);async function submit(){setBusy(true);setError('');try{const d=await run(()=>api('/admin/import-supabase',{method:'POST',body:JSON.stringify({faculty_password:facultyPassword||null,student_password:studentPassword||null})}));setStats(d);students.refresh();setFacultyPassword('');setStudentPassword('')}catch(e){setError(errMsg(e))}finally{setBusy(false)}}return <><PageHeader code="SUPABASE INTEGRATION" title="Import Your Existing College" sub="Import public.students and public.faculty into PULSEIQ's role-secured application tables, without duplicating your Supabase database."/><div className="grid g2"><Panel title="Database synchronization" sub="Uses the existing Render DATABASE_URL; no Supabase secret belongs in React."><div className="stack"><div className="callout"><b>Required:</b> `public.colleges`, `public.students`, and `public.faculty`. The college email domain must match the administrator's PULSEIQ college domain.</div><FormField label="Temporary password for NEW faculty accounts (optional)"><input className="inp" type="password" minLength={12} value={facultyPassword} onChange={e=>setFacultyPassword(e.target.value)} placeholder="Leave blank to skip creating accounts" autoComplete="new-password"/></FormField><FormField label="Temporary password for NEW student accounts (optional)"><input className="inp" type="password" minLength={12} value={studentPassword} onChange={e=>setStudentPassword(e.target.value)} placeholder="Leave blank to skip creating accounts" autoComplete="new-password"/></FormField><button className="btn primary" disabled={busy} onClick={submit}><Database size={17}/>{busy?'Importing…':'Import students and faculty'}</button><p className="hint">Existing accounts and passwords are kept unchanged. New accounts use hashed passwords. Rotate any shared demo passwords after import.</p>{error&&<StatusLine error>{error}</StatusLine>}</div></Panel><Panel title="Import verification" sub="Application roster count after import"><Kpi title="Students available in Admin roster" value={students.data?.items?.length??'—'} subtitle="Live pi3_roster count"/>{stats&&<div className="stack" style={{marginTop:14}}>{Object.entries(stats).map(([k,v])=><div key={k} className="row spread"><span>{k.replaceAll('_',' ')}</span><b className="mono">{String(v)}</b></div>)}</div>}</Panel></div><Panel title="After importing"><p>Assign each faculty member to the correct department, semester and section in <b>Teaching Assignments</b>. Faculty student lists are intentionally scoped to assigned classes; students with no matching assignments will not appear in their faculty view.</p></Panel></>}
function ConnectorsPage(){const {nonce,run}=useApp();const x=useRemote<any>('/admin/connections',[nonce]);return <><PageHeader code="SOURCE INTEGRATION" title="External Database Connections" sub="The current Supabase project is your application database. Optional connectors let authorized administrators import institutional data with validated field mappings."/>{x.busy?<Loading/>:x.error?<ErrorText error={x.error} refresh={x.refresh}/>:<Panel title="Configured external data sources" sub="Connection secrets are never sent back to the browser"><div className="tw"><table><thead><tr><th>Source</th><th>Type</th><th>Created</th><th>Actions</th></tr></thead><tbody>{(x.data?.items||[]).map((s:any)=><tr key={s.id}><td><b>{s.name}</b></td><td>{s.kind}</td><td>{s.created_at?.slice(0,10)}</td><td><div className="row"><button className="btn sm" onClick={async()=>{try{const p=await api(`/admin/connections/${s.id}/preview`);alert(`Preview: ${JSON.stringify(p.counts)}\nWarnings: ${p.warnings?.length||0}`)}catch(e){alert(errMsg(e))}}}>Preview</button><button className="btn sm" onClick={async()=>{if(!confirm('Sync data from this source now?'))return;try{await run(()=>api(`/admin/connections/${s.id}/sync`,{method:'POST'}));alert('Sync complete')}catch{}}}>Sync</button><button className="btn sm danger" onClick={async()=>{if(!confirm('Remove this connector?'))return;try{await run(()=>api(`/admin/connections/${s.id}`,{method:'DELETE'}));x.refresh()}catch{}}}>Remove</button></div></td></tr>)}</tbody></table>{!x.data?.items?.length&&<Empty>No external connectors configured. For your Supabase demo, use the dedicated Supabase Import screen instead.</Empty>}</div></Panel>}<Panel title="What connection methods are implemented?" sub="API supports credential storage, discovery, mapping, preview and sync"><p>External PostgreSQL, MySQL, SQL Server and REST source workflows require valid network access, read-only credentials and mappings. The Supabase project itself is already connected through Render's DATABASE_URL.</p></Panel></>}
function AuditPage(){const x=useRemote<any>('/admin/audit');return <><PageHeader code="GOVERNANCE" title="Audit & Activity Log" sub="Recent database-recorded administrative and academic actions."/>{x.busy?<Loading/>:x.error?<ErrorText error={x.error} refresh={x.refresh}/>:<Panel title="Recent events"><div className="tw"><table><thead><tr><th>Time</th><th>Action</th><th>Details</th><th>Actor ID</th></tr></thead><tbody>{(x.data?.items||[]).map((a:any)=><tr key={a.id}><td>{a.at}</td><td><Tag kind="acc">{a.event}</Tag></td><td className="mono small">{JSON.stringify(a.details)}</td><td className="mono small">{a.actor_id||'System'}</td></tr>)}</tbody></table>{!x.data?.items?.length&&<Empty>No audit events yet.</Empty>}</div></Panel>}</>}
function SecurityPage(){const {user,run}=useApp();return <><PageHeader code="ACCOUNT & SECURITY" title="Account Settings" sub="Your current authenticated PULSEIQ college account."/><Panel title="Signed-in identity"><div className="stack"><div className="row spread"><span>Name</span><b>{user.full_name}</b></div><div className="row spread"><span>Email</span><b>{user.email}</b></div><div className="row spread"><span>Role</span><Tag kind="acc">{user.role}</Tag></div><div className="row spread"><span>College</span><b>{user.college_name}</b></div><div className="row spread"><span>Departments</span><b>{user.departments?.join(', ')||'—'}</b></div></div></Panel><Panel title="Change your password" sub="Requires your current password; do not reuse a temporary demo password."><WorkingForm fields={[{key:"current_password",label:"Current password",type:"password"},{key:"new_password",label:"New password (12+ characters)",type:"password",minLength:12}]} submit={async(d:any)=>{await run(()=>api("/auth/change-password",{method:"POST",body:JSON.stringify(d)}));alert("Password updated successfully")}}/></Panel></>}
